import type { GunModule } from './api';
import { assembleGun } from './lib/guns-c-build';
import { M7_LAYOUT, M7_OPTIC } from './lib/guns-c-layout';
import { tunedFinish, type FinishTweak } from './lib/guns-c-materials';
import { buildHoloSight } from './lib/guns-c-optic';

/**
 * M7 rifle (SIG MCX-SPEAR, 6.8 x 51 mm) as issued: 13 in barrel with its
 * suppressor, coyote anodised receivers and handguard, folding stock,
 * 20-round magazine. An original model made for this game: the mesh and its
 * textures are generated by scripts/process-gun-m7.mjs (headless Blender,
 * scripts/blender/). The holographic sight is modelled in code
 * (lib/guns-c-optic.ts) and sits on the receiver's rail. 0.914 m long; the
 * grip centre is the origin.
 *
 * Moving parts, each resting at the identity under a holder at its pivot:
 * bolt carrier (seen through the ejection port) and the rear charging handle
 * (slide back along +Z by `cycleTravel`), magazine with its top cartridge
 * (drop along -Y) and trigger (hinged at its pin, about X). The left-side
 * charging handle is fixed, folded forward.
 */
// The textures are baked for this game's lighting, so they pass through almost unchanged.
const FINISH: FinishTweak = {
  tint: 0xffffff,
  metalLift: 0,
  polymerLift: 0,
  roughness: 1,
  roughnessBias: 0,
  scratchGloss: 0,
  minRoughness: 0.2,
  maxRoughness: 0.97,
  metalness: 1,
  wear: 0.08,
  noiseScale: 60,
  rub: 0,
  normalScale: 1,
};

const gun: GunModule = {
  weaponId: 'm7',
  assets: [M7_LAYOUT.asset],
  build(assets) {
    const model = assembleGun(assets.model(M7_LAYOUT.asset), M7_LAYOUT, (source) => tunedFinish(source, FINISH));
    const sight = buildHoloSight();
    sight.position.set(0, M7_OPTIC.railTop, M7_OPTIC.window);
    model.root.add(sight);
    return model;
  },
};

export default gun;
